import{_ as i,a0 as s,w as r,s as a,ao as l,I as p,x as n,a1 as o,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Ubuntu vs. openSUSE：不同的公司控制風格的比較 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu vs. openSUSE：不同的公司控制風格的比較 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu vs. openSUSE：不同的公司控制風格的比較 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu vs. openSUSE：不同的公司控制風格的比較 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Ubuntu vs. openSUSE--Weighing different styles of corporate control","title":"Ubuntu vs. openSUSE：不同的公司控制風格的比較","tag":"201311","desc":""},"relativePath":"201311/Ubuntu vs. openSUSE--Weighing different styles of corporate control.md","filePath":"[post].md"}'),S={name:"201311/Ubuntu vs. openSUSE--Weighing different styles of corporate control.md"};function U(d,t,f,m,x,b){const e=s("Link");return r(),a("div",null,[t[11]||(t[11]=l('<h1 id="ubuntu-vs-opensuse-不同的公司控制風格的比較" tabindex="-1">Ubuntu vs. openSUSE：不同的公司控制風格的比較 <a class="header-anchor" href="#ubuntu-vs-opensuse-不同的公司控制風格的比較" aria-label="Permalink to “Ubuntu vs. openSUSE：不同的公司控制風格的比較”">​</a></h1><p><em>Ubuntu和OpenSUSE以不同的方式發展他們的Linux發行版。你覺得哪種好？</em></p><p>相當多的linux開發都接受來自那些有意改善Linux的公司的資助，這早已不是秘密（這裏的Linux我指的是組成一個完整Linux系統的任何部分）。但是，許多公司進行資助的方式卻有很大不同。</p><p>讓我們看看兩個很典型的例子：Ubuntu和openSUSE。</p><p>這兩者都是Linux發行版。兩者都是一個規模龐大、長期持續且非常成功的項目，並且它們都有一個包括志願者和付費職員的大型社區。然而，兩者之間的不同還是相當明顯而且非常重要。</p><p>對於Ubuntu，它發展的主要方向是由Canonical的團隊及其領袖Mark Shuttleworth決定的。當談到Canonical真正“掌舵”Ubuntu時，我們能很快就會想起兩個例子，例如Unity（Ubuntu自己的用户界面）和Mir（Ubuntu自己的顯示服務）。在許多事情上，母公司都會在沒有協商（可以這麼説）的情況下設定目標、項目和優先級。例如，Ubuntu的Unity用户界面對於Canonical公司廣泛戰略目標來説是必須的。一些社區成員喜歡它，另一些則討厭它。但是不管怎麼説，Unity都已經成為Ubuntu的默認用户界面了。</p><p>但是這是一件壞事嗎？我不確信它到底是好還是壞。這只是這個項目如何與公司相處的問題。</p><p>於此形成對比的是openSUSE，它也有一個公司掌控者，好吧，就是SUSE。關鍵的不同點是SUSE以“SUSE Linux企業版”的形式提供一個商業發行版。儘管openSUSE（社區Linux發行版）與SUSE Linux發行版（商業發行版）在技術上有許多重疊之處...然而專業的説，兩者是不同的。</p><p>這意味着SUSE，作為一個公司，對待openSUSE時可以更多的採取放手不管的方式，他們的興趣就是尋找那些被改善的關鍵性技術（例如，Btrfs文件系統），檢測以及打包社區發行版中那些他們想包含在商業發行版中的軟件包，但是社區發行版與商業發行版分離的方式與Canonical採取方式相比，給他們提供了更大的靈活性。在這方面，和Canonical不同。</p><p>這種方法和紅帽對待Fedora的方式非常相似，已經成為了一個公司使用社區Linux發行版為基礎，銷售企業級的Linux系統的一種成功之路。</p><p>不過，坦白的説兩種模式我都看到了優點和缺點。在組織上以及管理上（公眾部分）他們都面臨着各自的難題。實際上，這兩種方法與它們的不同點比起來，相同點更多一些。</p><p>我非常願意聽到你們對此的看法。你是更喜歡你的以社區為基礎的Linux發行版有一個單一的領袖？還是更喜歡你Linux發行版的大多數決定都是有社區驅動的呢？公司是否應該強勢控制Linux發行版，還是應該大膽放手讓社區來決定呢？請在評論裏留言，讓我們知道你的看法。</p><hr>',13)),p("p",null,[t[1]||(t[1]=n("via: ",-1)),o(e,{href:"http://www.networkworld.com/community/node/84250"},{default:u(()=>[...t[0]||(t[0]=[n("http://www.networkworld.com/community/node/84250",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=n("譯者：",-1)),o(e,{href:"https://github.com/Linux-pdz"},{default:u(()=>[...t[2]||(t[2]=[n("Linux-pdz",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:u(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:u(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const C=i(S,[["render",U]]);export{T as __pageData,C as default};
